package com.takago.app.driver;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.takago.app.db.SessionManager;import com.takago.app.network.ApiClient;import org.json.*;import java.util.*;
public class DriverCashActivity extends AppCompatActivity{
 private LinearLayout list;private SessionManager session;private final List<Integer> selected=new ArrayList<>();
 protected void onCreate(Bundle b){super.onCreate(b);session=new SessionManager(this);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(32,40,32,32);TextView title=new TextView(this);title.setText("Cash held and remittance");title.setTextSize(22);title.setTextColor(0xFF17324D);page.addView(title);TextView note=new TextView(this);note.setText("Select cash payments being handed to the waste operator. Your balance reduces only after operator verification.");note.setPadding(0,12,0,20);page.addView(note);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));Button submit=new Button(this);submit.setText("Submit selected cash");submit.setOnClickListener(v->submit());page.addView(submit);setContentView(page);load();}
 private void load(){ApiClient.get("/payments",session.getApiToken(),new ApiClient.JsonCallback(){public void onSuccess(JSONObject json){runOnUiThread(()->{list.removeAllViews();JSONArray rows=json.optJSONArray("data");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject p=rows.optJSONObject(i);if(p==null||!"held_by_driver".equalsIgnoreCase(p.optString("cash_status")))continue;int id=p.optInt("id");double amount=p.optDouble("amount");CheckBox box=new CheckBox(DriverCashActivity.this);box.setText(p.optString("provider_reference","Cash payment #"+id)+"  •  TZS "+String.format(Locale.US,"%,.0f",amount));box.setOnCheckedChangeListener((button,checked)->{if(checked)selected.add(id);else selected.remove(Integer.valueOf(id));});list.addView(box);}});}public void onError(String m){runOnUiThread(()->Toast.makeText(DriverCashActivity.this,m,Toast.LENGTH_LONG).show());}});}
 private void submit(){if(selected.isEmpty()){Toast.makeText(this,"Select at least one cash payment",Toast.LENGTH_SHORT).show();return;}try{JSONArray ids=new JSONArray();for(int id:selected)ids.put(id);JSONObject body=new JSONObject().put("payment_ids",ids);ApiClient.post("/cash-remittances",session.getApiToken(),body,new ApiClient.JsonCallback(){public void onSuccess(JSONObject j){runOnUiThread(()->{Toast.makeText(DriverCashActivity.this,"Submitted for operator verification",Toast.LENGTH_LONG).show();selected.clear();load();});}public void onError(String m){runOnUiThread(()->Toast.makeText(DriverCashActivity.this,m,Toast.LENGTH_LONG).show());}});}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
}
